'use strict';
// Run: node --test tests/app-invite-pages.test.cjs
// Joe, 2026-11-23: every app gets a branded invite link: icon + "You're invited to join for free",
// three buttons Apple / Google / Web. Pages are generated by tools/build-invite-pages.py.
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const test = require('node:test');
const { execFileSync } = require('node:child_process');

const root = path.join(__dirname, '..');
const PAGES = [
  // dir, App Store id when the listing is live (else null), web home
  ['games/kmob/invite', '6822852714', '/games/kmob/'],
  ['app/wifi-remote/invite', '6790006312', '/'],
  ['invite', null, '/'],
  ['app/findmyweed/invite', null, '/app/findmyweed/'],
  ['app/kaitarako/invite', null, '/app/kaitarako/'],
];

function buttons(html) {
  return [...html.matchAll(/<(a|span) class="btn ([a-z]+)"([^>]*)>([\s\S]*?)<\/\1>/g)].map((m) => ({
    tag: m[1], kind: m[2], attrs: m[3], text: m[4].replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim(),
  }));
}

function problems(html, apple, web) {
  const out = [];
  const b = buttons(html);
  const want = [apple ? 'Apple' : 'Apple Coming soon', 'Google Coming soon', 'Web'];
  if (JSON.stringify(b.map((x) => x.text)) !== JSON.stringify(want)) out.push('buttons ' + JSON.stringify(b.map((x) => x.text)));
  if (apple && (!b[0] || b[0].tag !== 'a' || b[0].attrs !== ` href="https://apps.apple.com/app/id${apple}"`)) out.push('apple link');
  if (!apple && b[0] && /href=/.test(b[0].attrs)) out.push('apple must not link before the listing is live');
  if (b[1] && /href=/.test(b[1].attrs)) out.push('google must not link (no Play listing)');
  if (!b[2] || b[2].tag !== 'a' || b[2].attrs !== ` href="${web}"`) out.push('web link');
  if (!/<p class="lead">You're invited to join for free\.<\/p>/.test(html)) out.push('text');
  const imgs = [...html.matchAll(/<img[^>]*src="([^"]+)"/g)].map((m) => m[1]);
  if (imgs.length !== 1) out.push('exactly one image (the icon)');
  else if (!fs.existsSync(path.join(root, imgs[0]))) out.push('icon file missing: ' + imgs[0]);
  if (/<script|<iframe|@import|play\.google\.com|https?:\/\/(?!keepitil\.com|apps\.apple\.com)/i.test(html)) out.push('external or scripted content');
  return out;
}

for (const [dir, apple, web] of PAGES) {
  test(`${dir}: icon, "join for free", Apple / Google / Web`, () => {
    const html = fs.readFileSync(path.join(root, dir, 'index.html'), 'utf8');
    assert.deepEqual(problems(html, apple, web), []);
  });
}

test('CONTROL: the check catches wrong order, a live Google link and a missing text', () => {
  const html = fs.readFileSync(path.join(root, 'games/kmob/invite/index.html'), 'utf8');
  assert.notDeepEqual(problems(html.replaceAll("You're invited to join for free.", 'Hi'), '6822852714', '/games/kmob/'), []);
  assert.notDeepEqual(problems(html.replace('<span class="btn disabled" role="link" aria-disabled="true"><svg class="glyph glyph-android"',
    '<span class="btn disabled" href="https://play.google.com/x"><svg class="glyph glyph-android"'), '6822852714', '/games/kmob/'), []);
  assert.notDeepEqual(problems(html, null, '/games/kmob/'), [], 'a live Apple link where none is expected is caught');
});

test('the pages are exactly what the generator writes', () => {
  const before = PAGES.map(([d]) => fs.readFileSync(path.join(root, d, 'index.html'), 'utf8'));
  execFileSync('python3', [path.join(root, 'tools/build-invite-pages.py')], { stdio: 'ignore' });
  PAGES.forEach(([d], i) => assert.equal(fs.readFileSync(path.join(root, d, 'index.html'), 'utf8'), before[i], d));
});
